function site_header(?array $user=null): void {?>
<header class="site-header"><div class="header-inner">
  <a class="logo" href="/">IMGTR<span>.</span></a>
  <nav class="main-nav"><a href="/"><?=e(t('nav_upload'))?></a><a href="/#features"><?=e(t('features'))?></a><a href="/faq"><?=e(t('nav_faq'))?></a><a href="/app"><?=e(t('nav_app'))?></a><a href="/api"><?=e(t('nav_api'))?></a></nav>
  <div class="header-actions"><details class="mobile-nav"><summary aria-label="<?=e(t('nav_menu'))?>"><i></i><i></i></summary><div><a href="/"><?=e(t('nav_upload'))?></a><a href="/#features"><?=e(t('features'))?></a><a href="/faq"><?=e(t('nav_faq'))?></a><a href="/app"><?=e(t('nav_app'))?></a><a href="/api"><?=e(t('nav_api'))?></a></div></details><?php language_picker();?><button class="theme-button" id="theme" aria-label="<?=e(t('theme'))?>">◐</button>
  <?php if($user):?><details class="account-menu"><summary><span><?=e(strtoupper(substr($user['email'],0,1)))?></span><b><?=e($user['email'])?></b><i aria-hidden="true"></i></summary><div><p><?=e($user['email'])?></p><a href="/dashboard"><?=e(t('dashboard'))?></a><?php if(($user['role']??'user')==='admin'):?><a href="/admin/"><?=e(t('admin'))?></a><?php endif?><a href="/logout"><?=e(t('logout'))?></a></div></details>
  <?php else:?><a class="login-link" href="/login"><?=e(t('login'))?></a><a class="header-cta" href="/register"><?=e(t('register'))?></a><?php endif?></div>
</div></header><?php }
function page_start(string $title,string $description='',array $seo=[]): void {secure_session();$user=current_user();header('Cache-Control: private, no-store, max-age=0');header('Vary: Cookie, Accept-Language');$index=(bool)($seo['index']??true);if(!$index)header('X-Robots-Tag: noindex, nofollow, noarchive');if($index)record_public_hit(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/');?><!doctype html><html lang="<?=e(current_language())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=csrf_token()?>"><?php seo_head($title,$description,$seo);?><link rel="stylesheet" href="/assets/css/premium.css?v=20260831g"></head><body><?php site_header($user);}
function site_footer(?array $user=null): void {?><footer class="site-footer"><div class="footer-brand"><a class="logo" href="/">IMGTR<span>.</span></a><p><?=e(t('footer_tagline'))?></p><small>IMAGE INFRASTRUCTURE / NOSTR RELAYS</small></div><div><b><?=e(t('footer_product'))?></b><a href="/app"><?=e(t('nav_app'))?></a><a href="/faq"><?=e(t('footer_faq'))?></a><a href="/api">API</a><a href="/status"><?=e(t('footer_status'))?></a></div><div><b><?=e(t('footer_legal'))?></b><a href="/terms"><?=e(t('footer_terms'))?></a><a href="/privacy"><?=e(t('footer_privacy'))?></a><a href="/report"><?=e(t('footer_report'))?></a></div><div><b><?=e(t('footer_account'))?></b><?php if($user):?><a href="/dashboard"><?=e(t('dashboard'))?></a><?php if(($user['role']??'user')==='admin'):?><a href="/admin/"><?=e(t('admin'))?></a><?php endif?><a href="/logout"><?=e(t('logout'))?></a><?php else:?><a href="/login"><?=e(t('login'))?></a><a href="/register"><?=e(t('register'))?></a><?php endif?></div></footer><?php }
function page_end(array $scripts=[]): void {$user=current_user();site_footer($user);?><div class="toast" id="toast"></div><script src="/assets/js/app.js?v=20260828c"></script><?php foreach($scripts as $script):?><script src="<?=e($script)?>"></script><?php endforeach?></body></html><?php }
